<script setup lang="ts">
import {computed,nextTick,onBeforeUnmount,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {agentWorkData} from '@/pinia/agentWork';import {usePhase1} from '@/pinia/phase1';import {loadAMap,convertGpsCoordinates} from '@/utils/amap';import {dateText,parseLocal,stateNames,sessionNames} from './catalog';import Clock from './Clock.vue';import OrderResults from './OrderResults.vue';import CorrectionDialog from './CorrectionDialog.vue';
const route=useRoute();const router=useRouter();const work=agentWorkData();const s=usePhase1();const search=ref('');const stateFilter=ref('');const open=ref(false);const feedback=ref('');const duration=ref(45);const distance=ref(1500);const tab=ref('运输过程');const correction=ref('');const stateCorrection=ref(false);
const timeline=[{state:'pending',title:'运单创建',key:'createdAt',action:'开始装货',next:'loading'},{state:'loading',title:'装货中',key:'enteredAt',action:'发出',next:'in_transit'},{state:'in_transit',title:'在途',key:'departedAt',action:'已到达',next:'arrived'},{state:'arrived',title:'已到达',key:'arrivedAt',action:'已完成',next:'completed'},{state:'completed',title:'已完成',key:'completedAt'}] as const;
function progress(next:import('@/views/AgentWork/interface').P1State){if(selected.value)feedback.value=s.progress(selected.value.id,next)||'运输状态已更新。';}
function correctState(){if(selected.value){stateCorrection.value=true;correction.value=selected.value.id;}}

const mode=computed(()=>route.path.endsWith('/detail')?'detail':route.path.endsWith('/risk')?'risk':'orders');
const base=computed(()=>s.orders.filter(o=>o.projectId===work.currentProjectId));const risks=(id:string)=>s.anomalies.filter(a=>a.orderId===id&&a.status==='active');
const orders=computed(()=>base.value.filter(o=>(!search.value||`${o.id} ${o.plate} ${o.source} ${o.origin.name} ${o.destination.name}`.includes(search.value))&&(!stateFilter.value||o.state===stateFilter.value)&&(mode.value!=='risk'||risks(o.id).length)));
const selected=computed(()=>base.value.find(o=>o.id===route.query.orderId)||(route.query.orderId?undefined:base.value[0]));
const form=ref({id:'',plate:'沪A90001',plateColor:2 as 1|2,driver:'演示司机',source:'手动录入',origin:'上海嘉定工厂',destination:'南京江宁仓',departure:'',arrival:''});
function newOrder(){form.value={id:`V11-NEW${s.sequence+1}`,plate:'沪A90001',plateColor:2,driver:'演示司机',source:'手动录入',origin:'上海嘉定工厂',destination:'南京江宁仓',departure:dateText(s.now+3600000).replace(' ','T'),arrival:dateText(s.now+4*3600000).replace(' ','T')};feedback.value='';open.value=true;}
function create(){const f=form.value;const ok=s.createOrder({id:f.id.trim(),projectId:work.currentProjectId,plate:f.plate.trim(),plateColor:f.plateColor,driver:f.driver,source:f.source,origin:{name:f.origin,lat:31.374,lon:121.265,radiusMeters:500,regionCode:'310114'},destination:{name:f.destination,lat:31.95,lon:118.84,radiusMeters:500,regionCode:'320115'},plannedDeparture:f.departure?parseLocal(f.departure):null,plannedArrival:f.arrival?parseLocal(f.arrival):null});feedback.value=ok?(s.orders.find(o=>o.id===f.id)?.state==='completed'?'运单按计划时间初始化为已完成，未注册在途监控。':'运单已按计划时间初始化，读取最新配置并建立模拟订阅；推进10分钟查看生效。'):s.error;if(ok){open.value=false;detail(f.id);}}
function detail(id:string){tab.value='运输过程';feedback.value='';router.push({path:'/index/detail',query:{orderId:id}});}
function event(type:'fence'|'parking'|'offline'|'deviation',phase:'started'|'recovered'|'enter'|'exit'='started',target?:'origin'|'destination'){if(!selected.value)return;const error=s.event(selected.value.id,type,phase,target,{durationMinutes:duration.value,distanceMeters:distance.value});feedback.value=error||'基础事件已采集，研判结果已记录。';}
const mapEl=ref<HTMLDivElement>();const mapError=ref(false);let map:AMap.Map|undefined;let generation=0;
async function mapDraw(){const g=++generation;map?.destroy();map=undefined;mapError.value=false;await nextTick();if(mode.value!=='detail'||!mapEl.value||!selected.value)return;const o=selected.value;
 try{const amap=await loadAMap();const points=await convertGpsCoordinates(amap,[[o.origin.lon,o.origin.lat],[o.destination.lon,o.destination.lat]]);if(g!==generation||!mapEl.value)return;map=new amap.Map(mapEl.value,{zoom:7,center:points[0]});map.add(points.map((p,i)=>new amap.Marker({position:p,title:i===0?o.origin.name:o.destination.name})));map.setFitView();}catch{if(g===generation)mapError.value=true;}}
watch([selected,mode],mapDraw,{immediate:true});onBeforeUnmount(()=>{generation++;map?.destroy();});
function planTime(kind:'departure'|'arrival',value:string){if(!selected.value)return;const time=value?parseLocal(value):null;if(time!==null&&!Number.isFinite(time)){feedback.value='计划时间格式无效';return;}const o=selected.value;const dep=kind==='departure'?time:o.plannedDeparture;const arr=kind==='arrival'?time:o.plannedArrival;if(dep&&arr&&arr<dep){feedback.value='预计到达不能早于预计出发';return;}o.plannedDeparture=dep;o.plannedArrival=arr;s.allLog(o,'配置','计划时间已更新；历史结果保留，未来计时重新计算，不延长72小时期限。');s.correctLate(o);s.tick();feedback.value='计划时间已保存。';}
function assessmentSample(type:'parking'|'offline',reasonable:boolean){
 if(!selected.value)return;const o=selected.value;const kind=type==='parking'?'服务区':'隧道';
 const error=s.event(o.id,type,'started',undefined,{durationMinutes:Math.max(duration.value,o.config[type].thresholdMinutes),address:`模拟${kind}${reasonable?'设施内':'附近主线'}`,poiEvidence:{source:'mock',pois:[{name:`模拟${kind}`,category:kind,distanceMeters:100,inside:reasonable}],normalActivityConfirmed:reasonable,durationMatches:reasonable,dangerousLocation:!reasonable,signalRecovered:reasonable,trackContinuous:reasonable}});
 feedback.value=error||'模拟POI证据已提交，查看事件与异常中的研判结果；需先开启对应异常研判。';
}
</script>
<template><div class="p1-desk" :class="{'p1-order-detail':mode==='detail'}"><header><h1>{{mode==='detail'?'运单详情':mode==='risk'?'异常运单列表':'运单列表'}}</h1><span>V1.1 · 一装一卸 · 本地 Demo</span><button @click="router.push({path:'/index/projects/config',query:{projectId:work.currentProjectId}})">项目配置</button><button v-if="mode==='detail'" @click="router.push('/index/orders')">返回运单列表</button><button v-else @click="newOrder" class="primary">新增运单</button></header><Clock v-if="mode!=='detail'"/><details v-else class="p1-section"><summary>本地演示时间与数据控制</summary><Clock/></details>
<template v-if="mode!=='detail'"><div class="p1-summary"><span>本项目 <strong>{{base.length}}</strong> 单</span><span>监听中 <strong>{{base.filter(o=>o.session==='active').length}}</strong></span><span>有异常 <strong>{{base.filter(o=>risks(o.id).length).length}}</strong> 单</span><span>退订待重试 <strong>{{base.filter(o=>o.session==='cleanup_pending').length}}</strong></span></div><div class="p1-toolbar"><input v-model="search" aria-label="搜索运单" placeholder="运单号 / 车牌 / 起终点"/><select v-model="stateFilter" aria-label="运单状态"><option value="">全部状态</option><option v-for="(name,key) in stateNames" :value="key" :key="key">{{name}}</option></select><button @click="router.push('/index/events')">基础事件列表</button><span>{{orders.length}}单</span></div><div class="p1-table"><table><thead><tr><th>运单 / 运力</th><th>起始地 → 目的地</th><th>运单状态</th><th>计划出发 / 到达</th><th>异常</th><th>监听与配置</th><th>操作</th></tr></thead><tbody><tr v-for="o in orders" :key="o.id"><td><strong>{{o.id}}</strong><small>{{o.plate}} · {{o.driver}}</small><small>{{o.source}}</small></td><td>{{o.origin.name}}<small>{{o.destination.name}}</small></td><td><span class="p1-tag">{{stateNames[o.state]}}</span></td><td>{{dateText(o.plannedDeparture)}}<small>{{dateText(o.plannedArrival)}}</small></td><td><span :class="{'p1-tag':true,danger:risks(o.id).length>0}">{{risks(o.id).length}} 个未恢复</span><small>{{risks(o.id).map(a=>a.kind).join('、')||'无'}}</small></td><td>{{sessionNames[o.session]}}<small>配置v{{o.config.version}} · 截止{{dateText(o.expiresAt)}}</small></td><td><button @click="detail(o.id)">查看详情</button><button @click="router.push({path:'/index/events',query:{orderId:o.id}})">事件</button></td></tr></tbody></table><p v-if="!orders.length" class="p1-empty">暂无匹配运单。可新增一装一卸运单。</p></div></template>
<template v-else-if="selected"><div class="p1-detail-overview"><div><small>运单号</small><strong>{{selected.id}}</strong></div><div><small>车辆 / 司机</small><strong>{{selected.plate}} · {{selected.driver}}</strong></div><div><small>运输状态</small><strong>{{stateNames[selected.state]}}</strong></div><div><small>监听状态</small><strong>{{sessionNames[selected.session]}}</strong></div><div><small>起始地</small><strong>{{selected.origin.name}}</strong></div><div><small>目的地</small><strong>{{selected.destination.name}}</strong></div></div><div class="p1-detail-layout"><section class="p1-detail-map-panel" aria-label="运单地图"><h2>起终点位置</h2><div class="p1-map"><div ref="mapEl" style="height:100%"></div><div v-if="mapError" class="p1-map-fallback">地图配置暂不可用<small>起终点坐标与事件信息仍可查看</small></div></div><p class="p1-muted">样例只提供起终点，不展示虚构的实际行驶轨迹。状态按计划时间推定，实际进出时间以围栏或人工记录为准。</p></section><section class="p1-detail-content" aria-label="运输信息"><nav class="p1-tabs"><button v-for="t in ['运输过程','事件与异常']" :key="t" :class="{active:tab===t}" @click="tab=t">{{t}}</button></nav><p v-if="feedback" role="status" class="p1-warning">{{feedback}}</p>
<div v-if="tab==='运输过程'" class="p1-detail-process"><section><div v-if="selected.initialization" class="p1-init-note"><strong>S00 · 初始状态{{stateNames[selected.initialization.state]}}</strong><p>{{selected.initialization.basis}}</p></div><div class="p1-timeline"><template v-for="item in timeline" :key="item.state"><article class="p1-milestone" :class="{done:!!selected[item.key],current:selected.state===item.state}"><h2>{{item.title}} <span v-if="selected.state===item.state" class="p1-tag">当前状态</span></h2><p>触发时间：{{dateText(selected[item.key])}}</p><small v-if="!selected[item.key]&&selected.initialization?.state===item.state">状态由S00按计划时间推定；尚无实际触发时间。</small><small>触发方式：{{item.state==='pending'?selected.source:selected[item.key]?(selected.milestoneMethods?.[item.state]||'围栏事件'):selected.initialization?.state===item.state?'S00计划时间推定':'待触发'}}</small><p v-if="item.state==='in_transit'||item.state==='arrived'">计划时间：{{dateText(item.state==='in_transit'?selected.plannedDeparture:selected.plannedArrival)}}</p><div v-for="a in s.anomalies.filter(a=>a.orderId===selected!.id&&a.kind===(item.state==='in_transit'?'晚发':item.state==='arrived'?'晚到':''))" :key="a.id" class="p1-warning"><strong>{{a.kind}} · {{a.status==='active'?'异常':a.status==='corrected'?'已纠正':'已恢复'}}</strong><p>{{a.reason}}</p><button @click="stateCorrection=false;correction=a.id">异常纠正</button></div><div class="p1-actions"><button v-if="'action' in item && selected.state===item.state" class="primary" @click="progress(item.next)">{{item.action}}</button><button v-if="selected[item.key]&&item.state!=='pending'&&item.state!=='completed'" @click="correctState">异常纠正</button></div></article><article v-if="item.state==='in_transit'" class="p1-continuous"><strong>运输过程 · {{selected.state==='completed'||selected.arrivedAt?'已结束':selected.state==='in_transit'||selected.departedAt?'持续中':'待开始'}}</strong><p class="p1-muted">发出 → 已到达，持续监听停车、离线与线路偏离</p><div v-for="a in s.anomalies.filter(a=>a.orderId===selected!.id&&!['晚发','晚到'].includes(a.kind))" :key="a.id" class="p1-row"><strong>{{a.kind}} · {{a.status==='active'?'异常':a.status==='corrected'?'已纠正':'已恢复'}}</strong><p>{{a.reason}}</p><small>{{dateText(a.firstAt)}} · 提醒{{a.repeatCount}}次</small><button @click="stateCorrection=false;correction=a.id">异常纠正</button></div><p v-if="!s.anomalies.some(a=>a.orderId===selected!.id&&!['晚发','晚到'].includes(a.kind))" class="p1-muted">暂无运输过程异常</p></article></template></div><details v-if="selected.corrections?.length"><summary>运输状态纠正记录</summary><p v-for="(c,i) in selected.corrections" :key="i">{{dateText(c.at)}} · {{c.before}} → {{c.after}} · {{c.reason}}</p></details><h2>恶劣天气监听</h2><p>{{s.weatherState(selected)}} · 预计生效：{{dateText(selected.weatherEffectiveAt)}}<br/>{{selected.subscriptionRevision===0?'未注册天气监听':'截止：'+dateText(selected.expiresAt)}} · 不发送车机提醒</p><h2>监听会话</h2><p>创建{{dateText(selected.createdAt)}} · {{selected.subscriptionRevision===0?'未注册监听':'生效'+dateText(selected.activateAt)}}<br/>{{selected.subscriptionRevision===0?'无监听截止':'固定截止'+dateText(selected.expiresAt)}} · 配置v{{selected.config.version}}</p><p v-if="selected.endReason">结束原因：{{selected.endReason}}</p><p v-if="selected.deviationBlocked" class="p1-error">偏离半径能力未确认，该项未生效。</p><button @click="router.push({path:'/index/daily-tasks',query:{projectId:selected.projectId,orderId:selected.id}})">查看任务运行结果</button><button v-if="selected.session==='cleanup_pending'" @click="s.retryCleanup(selected.id)">重试退订</button></section>
</div><section v-if="tab==='事件与异常'"><OrderResults :order-id="selected.id"/></section>
<details v-if="tab==='运输过程'" class="p1-section"><summary>演示控制与计划时间</summary><section><p>事件只写入当前单；请先推进到订阅生效时间。停车、离线开启异常研判后会使用模拟POI证据；未接真实POI或LLM。</p><h2>进出围栏</h2><div class="p1-actions"><button @click="event('fence','enter','origin')">进入起始地</button><button @click="event('fence','exit','origin')">离开起始地</button><button @click="event('fence','enter','destination')">进入目的地</button><button @click="event('fence','exit','destination')">离开目的地</button></div><h2>三类在途异常</h2><label>持续时长（分钟）<input type="number" min="1" v-model.number="duration"/></label><label>偏离距离（米）<input type="number" min="1" v-model.number="distance"/></label><div class="p1-actions"><button @click="event('parking')">触发停车告警</button><button @click="event('offline')">触发离线告警</button><button @click="event('deviation')">触发偏离告警</button><button @click="event('parking','recovered')">停车恢复</button><button @click="event('offline','recovered')">离线恢复</button><button @click="event('deviation','recovered')">偏离恢复</button></div><h2>POI与LLM研判演示</h2><p>先在项目配置开启对应异常研判。以下地点与轨迹证据均为模拟；不同样例之间请推进模拟时间，避免同一时刻事件去重。</p><div class="p1-actions"><button @click="assessmentSample('parking',true)">模拟服务区合理停车</button><button @click="assessmentSample('parking',false)">模拟服务区附近主线停车</button><button @click="assessmentSample('offline',true)">模拟隧道合理离线</button><button @click="assessmentSample('offline',false)">模拟隧道附近证据不足</button></div><h2>恶劣天气消息演示</h2><p>天气开关开启后，在预计生效时间后模拟消息。不同消息各生成异常，重复消息去重，不自动恢复。</p><button @click="feedback=s.weatherSample(selected.id)||'天气事件已采集，直接生成恶劣天气异常。'">模拟暴雨预警</button><button @click="feedback=s.weatherSample(selected.id,'危险路段','非天气消息')">模拟非天气消息过滤</button><h2>订阅结束</h2><label><input type="checkbox" v-model="selected.cleanupWillFail"/>下一次退订模拟失败</label><button @click="s.stop(selected.id)">取消本单监听</button><button v-if="selected.session==='cleanup_pending'" @click="s.retryCleanup(selected.id)">重试退订</button><p class="p1-muted">取消或72小时结束不会强行把业务状态改为已完成；未恢复异常保持事实记录。</p></section>
<section><label>预计出发时间<input type="datetime-local" :value="selected.plannedDeparture?dateText(selected.plannedDeparture).replace(' ','T'):''" @change="planTime('departure',($event.target as HTMLInputElement).value)"/></label><label>预计到达时间<input type="datetime-local" :value="selected.plannedArrival?dateText(selected.plannedArrival).replace(' ','T'):''" @change="planTime('arrival',($event.target as HTMLInputElement).value)"/></label><p class="p1-muted">无计划时间的规则待补齐；不以创建时间替代，不延长72小时截止。</p></section></details>
</section></div><CorrectionDialog v-if="correction" :key="correction" :id="correction" :state="stateCorrection?selected.state:undefined" @close="correction=''"/>
</template><p v-else class="p1-empty">当前项目没有该运单。</p>
<div v-if="open" class="p1-overlay"><section class="p1-dialog" role="dialog" aria-modal="true" aria-label="新增一装一卸运单"><header><h2>新增一装一卸运单</h2><button @click="open=false">取消</button></header><p class="p1-muted">使用上海→南京样例坐标与区县编码，名称可修改；S00按计划出发和到达时间初始化状态，不回补历史轨迹。</p><label>运单号<input v-model="form.id"/></label><label>车牌<input v-model="form.plate"/></label><label>车牌颜色<select v-model.number="form.plateColor"><option :value="1">蓝色</option><option :value="2">黄色</option></select></label><label>司机<input v-model="form.driver"/></label><label>来源<select v-model="form.source"><option>手动录入</option><option>Excel导入</option><option>上游系统</option><option>自然语言</option><option>SaaS同步</option></select></label><label>起始地<input v-model="form.origin"/></label><label>目的地<input v-model="form.destination"/></label><label>预计出发<input type="datetime-local" v-model="form.departure"/></label><label>预计到达<input type="datetime-local" v-model="form.arrival"/></label><p class="p1-error" role="status">{{feedback}}</p><button class="primary" @click="create">创建并初始化</button></section></div></div></template>
<style src="./phase.css"></style>

<style scoped>
.p1-order-detail{display:flex;flex-direction:column;overflow:hidden;padding:12px 16px;font-size:13px;background:#f7f7f5}.p1-order-detail>header{flex-shrink:0;padding:0 0 10px;margin-bottom:10px}.p1-order-detail h1{font-size:14px}.p1-order-detail h2{font-size:14px}.p1-order-detail button{font-size:12px;padding:5px 8px}.p1-detail-overview{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:10px;padding:12px;background:white;border:1px solid #deded9;border-radius:6px;margin-bottom:12px}.p1-detail-overview>div{padding:8px;background:#f7f7f5;min-width:0}.p1-detail-overview strong{display:block;font-size:13px;font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.p1-detail-layout{display:grid;grid-template-columns:minmax(0,1.15fr) minmax(0,.85fr);gap:16px;flex:1;min-height:0}.p1-detail-map-panel,.p1-detail-content{background:white;border:1px solid #deded9;border-radius:6px;min-width:0;overflow:hidden}.p1-detail-map-panel{display:flex;flex-direction:column}.p1-detail-map-panel>h2{height:46px;margin:0;padding:12px 16px;border-bottom:1px solid #e2e2dc}.p1-detail-map-panel .p1-map{flex:1;min-height:240px;height:auto}.p1-detail-map-panel>p{padding:10px 14px;margin:0}.p1-detail-content{overflow:auto;padding:0 16px 16px}.p1-detail-content>.p1-tabs{position:sticky;top:0;z-index:2;background:white;margin:0 -16px 12px;padding:0 16px;border-bottom:1px solid #e2e2dc;gap:20px}.p1-detail-content>.p1-tabs button{border:0;border-radius:0;padding:13px 0;background:white;color:#64748b}.p1-detail-content>.p1-tabs button.active{color:#263f5a;border-bottom:2px solid #263f5a}.p1-detail-process{min-width:0}.p1-init-note{font-size:12px;background:#f4f6f8;padding:10px 12px;margin:10px 0}.p1-init-note p{margin:5px 0;color:#657389}.p1-order-detail>.p1-section{flex-shrink:0;padding:5px 0;margin-bottom:10px}.p1-order-detail .p1-timeline{padding-left:7px}.p1-order-detail .p1-milestone{padding-left:20px}.p1-order-detail .p1-continuous{padding-left:20px}
@media(max-width:950px){.p1-order-detail{overflow:auto;display:block}.p1-detail-layout{grid-template-columns:1fr}.p1-detail-overview{grid-template-columns:repeat(3,minmax(0,1fr))}.p1-detail-map-panel .p1-map{height:300px;flex:none}.p1-detail-content{overflow:visible}}@media(max-width:600px){.p1-detail-overview{grid-template-columns:repeat(2,minmax(0,1fr))}}
